function calcular(datos) {
  var validos = { confirmado: true, enviado: true, entregado: true, novedad: true };
  var corte = Date.parse(datos.hoy) - 60 * 86400000;
  var conteo = {};
  var pedidos = datos.pedidos || [];
  for (var i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (!validos[p.estado]) continue;
    if (!p.creado) continue;
    var t = Date.parse(p.creado);
    if (isNaN(t) || t < corte) continue;
    var c = p.clienteId || "__sin_cliente__";
    conteo[c] = (conteo[c] || 0) + 1;
  }
  var conCompra = 0;
  var recurrentes = 0;
  for (var k in conteo) {
    if (Object.prototype.hasOwnProperty.call(conteo, k)) {
      conCompra++;
      if (conteo[k] > 1) recurrentes++;
    }
  }
  if (conCompra === 0) {
    return { valor: 0, unidad: "%", nota: "Sin compras confirmadas en los últimos 60 días; se cuentan confirmado, enviado, entregado y novedad." };
  }
  var pct = (recurrentes / conCompra) * 100;
  pct = Math.round(pct * 10) / 10;
  return { valor: pct, unidad: "%", nota: recurrentes + " de " + conCompra + " clientes con compra repitieron en los últimos 60 días; se cuentan confirmado, enviado, entregado y novedad." };
}

function consultar(datos) {
  var fmt = function (iso) {
    if (!iso) return null;
    var t = Date.parse(iso);
    if (isNaN(t)) return null;
    return new Date(t - 5 * 3600 * 1000).toISOString().slice(0, 16).replace("T", " ");
  };
  var esCompra = function (e) {
    return e === "confirmado" || e === "enviado" || e === "entregado" || e === "novedad";
  };
  var clientes = datos.clientes || [];
  var pedidos = datos.pedidos || [];
  var acc = {};
  var i;
  for (i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (!p || !esCompra(p.estado)) continue;
    var cid = p.clienteId;
    if (!cid) continue;
    if (!acc[cid]) acc[cid] = { total: 0, n: 0, ult: null, ultT: -1 };
    var tot = typeof p.total === "number" ? p.total : 0;
    acc[cid].total += tot;
    acc[cid].n += 1;
    var t = Date.parse(p.creado);
    if (!isNaN(t) && t > acc[cid].ultT) { acc[cid].ultT = t; acc[cid].ult = p.creado; }
  }
  var filas = [];
  var j;
  for (j = 0; j < clientes.length; j++) {
    var c = clientes[j];
    var a = acc[c.id] || { total: 0, n: 0, ult: null };
    filas.push({
      cliente: c.nombre || "Sin nombre",
      telefono: c.telefono || null,
      num_pedidos: a.n,
      total_comprado: a.total,
      ultima_compra: a.ult ? fmt(a.ult) : null,
      nota: a.n > 0 ? "Suma pedidos confirmado, enviado, entregado y novedad; excluye pendiente y cancelado." : "Sin compras confirmadas."
    });
  }
  filas.sort(function (x, y) {
    if (y.total_comprado !== x.total_comprado) return y.total_comprado - x.total_comprado;
    if (y.num_pedidos !== x.num_pedidos) return y.num_pedidos - x.num_pedidos;
    return x.cliente < y.cliente ? -1 : 1;
  });
  return filas.slice(0, 200);
}

function calcular(datos) {
  var pedidos = (datos && datos.pedidos) || [];
  var entregados = [];
  for (var i = 0; i < pedidos.length; i++) {
    if (pedidos[i] && pedidos[i].estado === 'entregado') entregados.push(pedidos[i]);
  }
  function obtenerInicio(p) {
    return p.confirmadoEn || p.confirmadaEn || p.fechaConfirmacion || p.fechaConfirmado || p.confirmado || null;
  }
  function obtenerFin(p) {
    return p.entregadoEn || p.entregadaEn || p.fechaEntrega || p.fechaEntregado || p.entregado || p.actualizadoEn || null;
  }
  var dias = [];
  for (var j = 0; j < entregados.length; j++) {
    var p = entregados[j];
    var ini = obtenerInicio(p);
    var fin = obtenerFin(p);
    if (!ini || !fin) continue;
    var tIni = Date.parse(ini);
    var tFin = Date.parse(fin);
    if (isNaN(tIni) || isNaN(tFin)) continue;
    var d = (tFin - tIni) / 86400000;
    if (d >= 0 && d < 365) dias.push(d);
  }
  if (dias.length === 0) {
    return { valor: 0, unidad: 'días', nota: 'Sin fechas de confirmación y entrega en los pedidos entregados no se puede calcular el promedio de ' + entregados.length + ' entregados.' };
  }
  var suma = 0;
  for (var k = 0; k < dias.length; k++) suma += dias[k];
  var prom = suma / dias.length;
  var red = Math.round(prom * 10) / 10;
  return { valor: red, unidad: 'días', nota: 'Promedio sobre ' + dias.length + ' de ' + entregados.length + ' pedidos entregados con fecha de confirmación y entrega.' };
}

function consultar(datos) {
  const dia = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  const fmt = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 16).replace("T", " ");
  const hoyDia = dia(datos.hoy);
  const clientesPorId = {};
  for (const c of datos.clientes) {
    clientesPorId[c.id] = c;
  }
  const porCliente = {};
  for (const m of datos.mensajes) {
    if (!m.creado) continue;
    if (dia(m.creado) !== hoyDia) continue;
    const id = m.clienteId;
    if (!porCliente[id]) {
      porCliente[id] = { deCliente: 0, deNegocio: 0, ultimo: null };
    }
    if (m.rol === "cliente") porCliente[id].deCliente += 1;
    else porCliente[id].deNegocio += 1;
    if (porCliente[id].ultimo === null || m.creado > porCliente[id].ultimo) {
      porCliente[id].ultimo = m.creado;
    }
  }
  const filas = [];
  for (const id in porCliente) {
    const g = porCliente[id];
    const cli = clientesPorId[id];
    filas.push({
      cliente: cli ? cli.nombre : "Cliente desconocido",
      telefono: cli ? cli.telefono : null,
      mensajes_cliente: g.deCliente,
      mensajes_negocio: g.deNegocio,
      total_mensajes: g.deCliente + g.deNegocio,
      ultima_hora: fmt(g.ultimo)
    });
  }
  filas.sort((a, b) => b.ultima_hora.localeCompare(a.ultima_hora));
  return filas.slice(0, 200);
}

