    total++;
    if (porCliente[k] > 1) repiten++;
  }
  var valor = 0;
  if (total > 0) valor = Math.round((repiten / total) * 1000) / 10;
  return {
    valor: valor,
    unidad: "%",
    nota: "De " + total + " clientes con compra en los ultimos 60 dias (" + inicioDia + " a " + hoyDia + "), " + repiten + " compraron mas de una vez; solo cuentan pedidos confirmados, enviados, entregados y novedad."
  };
}

